#include <LVRS/PlatformInfo.h>
#include "LegacyPlatformProfiles.generated.h"
#include <iiSDKCore/Core/Platform/PlatformProfile.h>
#include <future>
#include <algorithm>
#include <iostream>
#include <stdexcept>
using Value=ii::core::Value;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(ii::core::Result<T> value){if(!value)throw std::runtime_error(value.error().message);return std::move(*value);}
template<class T>T field(const Value& value,std::string_view key){return take(take(value.find(key)).get().get<T>()).get();}
lvrs::PlatformInfo platform(std::string os="macos",bool metal=true,bool vulkan=true){return lvrs::PlatformInfo({std::move(os),"arm64",metal,vulkan});}
Value expected(std::string target,std::string host,std::string requested,bool metal,bool vulkan){
    const auto value=platform_oracle::profile(target);auto result=take(value.get<Value::Object>()).get();
    const auto graphics=field<std::string>(value,"backend");const bool ready=target!="unknown"&&(graphics=="metal"?metal:graphics=="vulkan"?vulkan:true);
    result.insert_or_assign("host",Value(host));result.insert_or_assign("requested",Value(requested));
    result.insert_or_assign("current",Value(target!="unknown"&&target==host));result.insert_or_assign("backendFeatureReady",Value(ready));
    result.insert_or_assign("adaptiveAnimatedTransitions",Value(ready&&target!="wasm"));return Value(std::move(result));
}
void aliases(){auto p=platform();for(const auto& [alias,target]:platform_oracle::aliases){check(p.normalizeTarget(alias)==target&&p.isKnownTarget(alias)&&p.supportsTargetGeneration(alias),"A legacy alias was lost");std::string upper(alias);for(auto& c:upper)if(c>='a'&&c<='z')c=char(c-'a'+'A');check(p.normalizeTarget(" \t"+upper+"\n")==target,"Target case/spacing changed an alias");}}
void groups(){auto p=platform();check(p.runtimeTargets()==std::vector<std::string>{"macos","linux","windows","ios","android","wasm"},"Runtime target ordering changed");check(p.desktopTargets()==std::vector<std::string>{"macos","linux","windows","wasm"}&&p.mobileTargets()==std::vector<std::string>{"ios","android"},"Desktop/mobile target membership changed");for(auto target:p.runtimeTargets()){check(p.targetIsDesktop(target)==(target!="ios"&&target!="android"),"Target desktop class differs");check(p.targetIsMobile(target)==(target=="ios"||target=="android"),"Target mobile class differs");}}
void getters(){for(auto target:platform().runtimeTargets()){auto p=platform(target);check(p.canonicalOs()==target&&p.os()==(target=="macos"?"osx":target)&&p.arch()=="arm64"&&p.targetMatchesCurrent(target),"Canonical/legacy OS or architecture getter differs");const auto flags=std::array{p.macos(),p.linux(),p.windows(),p.ios(),p.android(),p.wasm()};check(std::ranges::count(flags,true)==1,"OS flags are not exclusive");check(p.mobile()==p.targetIsMobile(target)&&p.desktop()==p.targetIsDesktop(target)&&p.graphicsBackend()==p.graphicsBackendFor(target),"Current target projection differs");}}
void profiles(){for(auto host:platform().runtimeTargets())for(bool metal:{false,true})for(bool vulkan:{false,true}){auto p=platform(host,metal,vulkan);for(auto target:p.runtimeTargets())check(p.runtimeProfile(target)==expected(target,host,target,metal,vulkan),"A complete 41-field platform profile differs from the reviewed original");check(p.runtimeProfile("haiku")==expected("unknown",host,"haiku",metal,vulkan),"Unknown profile fields differ");}}
void features(){auto p=platform("linux",false,false);check(!p.metalSupported()&&!p.vulkanSupported()&&!p.backendFeatureReadyFor("macos")&&!p.backendFeatureReadyFor("ios")&&!p.backendFeatureReadyFor("android"),"Build feature gates were fabricated");for(auto target:{"linux","windows","wasm"})check(p.backendFeatureReadyFor(target),"Original default/D3D11 feature-gate semantics changed");check(!p.backendFeatureReadyFor("")&&!p.backendFeatureReadyFor("unknown")&&p.supportsTargetGeneration("ios"),"Feature availability was confused with template generation");}
void empty(){auto p=platform();check(!p.isKnownTarget("")&&p.normalizeTarget("  ").empty()&&!p.targetMatchesCurrent(""),"Empty predicate unexpectedly used the host");check(p.graphicsBackendFor("  ")=="metal"&&p.runtimeProfile(" \n")==expected("macos","macos","",true,true),"Empty defaulted profile/backend did not use the host");check(p.runtimeProfile(" Darwin ")==expected("macos","macos","Darwin",true,true),"The trimmed original request was not preserved");}
void unicode(){auto p=platform();for(auto space:{"\xc2\x85","\xc2\xa0","\xe1\x9a\x80","\xe2\x80\x80","\xe2\x80\x8a","\xe2\x80\xa8","\xe2\x80\xa9","\xe2\x80\xaf","\xe2\x81\x9f","\xe3\x80\x80"})check(p.normalizeTarget(std::string(space)+"MaCoS"+space)=="macos","Unicode whitespace was not trimmed");check(p.normalizeTarget("\xef\xbb\xbfmacos").empty(),"A non-space BOM was trimmed");}
void unknown(){auto p=platform("haiku");check(p.canonicalOs()=="unknown"&&p.os()=="unknown"&&!p.mobile()&&!p.desktop(),"Unknown host classification changed");check(p.runtimeProfile()==expected("unknown","unknown","",true,true),"Unknown default host was classified as supported");check(p.normalizeTarget("macos-extra").empty()&&p.graphicsBackendFor("macos-extra")=="default"&&!p.supportsTargetGeneration("macos-extra"),"Unknown token was partially matched");}
void list(){auto p=platform();const auto values=p.runtimeProfiles();const auto targets=p.runtimeTargets();check(values.size()==targets.size(),"Runtime profiles lost target ordering");for(std::size_t i=0;i<values.size();++i)check(values[i]==p.runtimeProfile(targets[i]),"Runtime profile list contains a different projection");}
void validation(){auto p=platform();bool rejected=false;try{(void)p.normalizeTarget(std::string(1,char(0xff)));}catch(const std::invalid_argument&){rejected=true;}check(rejected,"Invalid UTF-8 was accepted");rejected=false;try{(void)lvrs::PlatformInfo({"macos","",true,true});}catch(const std::invalid_argument&){rejected=true;}check(rejected,"Empty architecture was accepted");check(!p.isKnownTarget(std::string("macos\0extra",11)),"Embedded NUL truncated a target");}
void independent(){auto mac=platform(),android=platform("android",false,true);const auto before=mac.runtimeProfiles();auto future=std::async(std::launch::async,[mac]{return mac.runtimeProfiles();});check(android.android()&&android.graphicsBackend()=="vulkan"&&mac.runtimeProfiles()==before&&future.get()==before,"Immutable platform contexts interfered or required an owner executor");}
void current(){lvrs::PlatformInfo p;const auto environment=lvrs::PlatformEnvironment::current();check(p.arch()==environment.architecture&&p.metalSupported()==environment.metal&&p.vulkanSupported()==environment.vulkan,"Default model did not use the SDK/build context");check(p.canonicalOs()==environment.canonical_os,"Core's current platform was replaced by a host override");}
}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"profiles";if(name=="aliases")aliases();else if(name=="groups")groups();else if(name=="getters")getters();else if(name=="profiles")profiles();else if(name=="features")features();else if(name=="empty")empty();else if(name=="unicode")unicode();else if(name=="unknown")unknown();else if(name=="list")list();else if(name=="validation")validation();else if(name=="independent")independent();else if(name=="current")current();else throw std::runtime_error("Unknown platform test");std::cout<<"Native platform "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
